-- +goose Up

-- Six "Line and light" invitation templates, one per occasion: Nocturne (wedding), Silk Knot (engagement),
-- Candlelight (birthday), Lullaby (baby shower), Lit Window (housewarming) and Afterglow (party). Each is a
-- DRAFT template with its first version (v1, published). Data only. The manifests are the canonical form of
-- internal/content/testdata/themes_v2/<slug>.json (what content.ValidateManifest accepts and the admin
-- API would store). Same shape as 00038. All six are free (is_premium defaults to false); an admin can
-- flag one premium later with the existing PATCH.
--
-- Rollout gate: status 'draft' keeps them out of the host picker and the public catalog. Publishing is
-- an admin PATCH of the template status; setting it back to 'draft' is the rollback.
--
-- sort_order: Nocturne 16 (after Mimosa 15), Silk Knot 27 (after Lovebirds 25), Candlelight 55 (after
-- Sprinkles 50), Lullaby 67 (after Clothesline 65), Lit Window 87 (after Welcome Home 85), Afterglow 108
-- (after Glitterball 107).

INSERT INTO templates (id, slug, name, tags, status, sort_order) VALUES
    ('01926a00-0000-7000-8000-00000000001c', 'nocturne', 'Nocturne', '{"occasions":["wedding"]}', 'draft', 16),
    ('01926a00-0000-7000-8000-00000000001d', 'silk-knot', 'Silk Knot', '{"occasions":["engagement"]}', 'draft', 27),
    ('01926a00-0000-7000-8000-00000000001e', 'candlelight', 'Candlelight', '{"occasions":["birthday","milestone-birthday"]}', 'draft', 55),
    ('01926a00-0000-7000-8000-00000000001f', 'lullaby', 'Lullaby', '{"occasions":["baby-shower"]}', 'draft', 67),
    ('01926a00-0000-7000-8000-000000000020', 'lit-window', 'Lit Window', '{"occasions":["housewarming"]}', 'draft', 87),
    ('01926a00-0000-7000-8000-000000000021', 'afterglow', 'Afterglow', '{"occasions":["party"]}', 'draft', 108);

