-- +goose Down

-- Dev only, same pattern as 00038: published versions are immutable, so the trigger is disabled for
-- the delete. Fails (and the whole Down rolls back) if an event pins a version or a template has a later
-- version; repin or delete those events first.
ALTER TABLE template_versions DISABLE TRIGGER template_versions_immutable;
DELETE FROM template_versions
WHERE version = 1
  AND template_id IN (
    '01926a00-0000-7000-8000-00000000001c',
    '01926a00-0000-7000-8000-00000000001d',
    '01926a00-0000-7000-8000-00000000001e',
    '01926a00-0000-7000-8000-00000000001f',
    '01926a00-0000-7000-8000-000000000020',
    '01926a00-0000-7000-8000-000000000021');
ALTER TABLE template_versions ENABLE TRIGGER template_versions_immutable;
DELETE FROM templates
WHERE id IN (
    '01926a00-0000-7000-8000-00000000001c',
    '01926a00-0000-7000-8000-00000000001d',
    '01926a00-0000-7000-8000-00000000001e',
    '01926a00-0000-7000-8000-00000000001f',
    '01926a00-0000-7000-8000-000000000020',
    '01926a00-0000-7000-8000-000000000021');
